import { useQuery } from '@tanstack/react-query';
import { claimsKey, isActive, listClaims, listVoidReasons, liveClaims, voidReasonsKey, type Claim } from '../claims/api';
import { GRADES, gradeOn, listPeople, peopleKey } from '../people/api';
import { listPeriods, periodDueTotal, periodsKey } from '../periods/api';
import { listRates, personDue, rateByGrade, ratesKey, sumDues } from '../rates/api';
import { heldOf } from '../rates/shares';
import { isReviewLate, useCap, useFloor, useLate, useReviewSla } from '../settings/api';
import { useSheetToday } from '../sheet/api';
import { Fig } from '../session/Fig';

/** Every status a claim's count is shown for. */
export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'] as const;

/** How many of the sheet's claims have the status. */
export function statusCount(claims: Claim[] | undefined, status: (typeof STATUSES)[number]): number {
  return (claims ?? []).filter((c) => c.status === status).length;
}

/** Per grade, the due-totals of the people not retired on it added up (n/a ones skipped), as the
 *  sheet's summary shows them. */
export function useGradeDues(sheetId: string, user: string): Record<string, string> {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId, user);
  const cap = useCap(sheetId, today);
  const charges = useLate(sheetId, today);
  const byGrade = rateByGrade(rates.data, today);
  const all = claims.data ?? [];
  const active = (people.data ?? []).filter((p) => !p.retired);
  const dueOf = (p: (typeof active)[number]) => personDue(liveClaims(all.filter((c) => c.personId === p.id), [p]),
    rates.data, (d) => gradeOn(p, d), byGrade.get(p.grade), floor, charges, cap,
    heldOf(p.id, all, people.data, rates.data, floor, charges));
  return Object.fromEntries(GRADES.map((g) => [g, sumDues(active.filter((p) => p.grade === g).map(dueOf))]));
}

/** A period's due-total minus the previous one's, two decimals, a minus sign when lower. */
export function dueChange(previous: string, current: string): string {
  const cents = Math.round(Number(current) * 100) - Math.round(Number(previous) * 100);
  return (cents < 0 ? '-' : '') + (Math.abs(cents) / 100).toFixed(2);
}

/** The sheet's summary, agreeing with the lists: per grade, how many people not retired are on it
 *  today, their due-totals added up (n/a ones skipped) and how many of them are active (see `isActive`); per period by from-date, its due-total and its change from the period before (none for the earliest); per status,
 *  how many claims have it; how many REVIEW claims are review-late (see `isReviewLate`); per void reason on the list, how many VOID claims were voided with it. */
export function Summary({ sheetId, user }: { sheetId: string; user: string }) {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const periods = useQuery({ queryKey: periodsKey(sheetId), queryFn: () => listPeriods(sheetId) });
  const voidReasons = useQuery({ queryKey: voidReasonsKey(sheetId), queryFn: () => listVoidReasons(sheetId) });
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId, user);
  const charges = useLate(sheetId, today);
  const reviewSla = useReviewSla(sheetId);
  const all = claims.data ?? [];
  const active = (people.data ?? []).filter((p) => !p.retired);
  const liveOf = (p: (typeof active)[number]) => liveClaims(all.filter((c) => c.personId === p.id), [p]);
  const gradeDues = useGradeDues(sheetId, user);
  const byStart = [...(periods.data ?? [])].sort((a, b) => a.from.localeCompare(b.from));
  const periodDues = byStart.map((p) => periodDueTotal(p, all, people.data, rates.data, floor, charges));

  return (
    <section>
      <h3>Summary</h3>
      <table>
        <tbody>
          {GRADES.map((g) => {
            const on = active.filter((p) => p.grade === g);
            return (
              <tr key={g}>
                <td>Grade {g}</td>
                <td>People <span data-testid={`summary-grade-${g}-count`}>{on.length}</span></td>
                <td>Due <span data-testid={`summary-grade-${g}-due-total`}><Fig>{gradeDues[g]}</Fig></span></td>
                <td>Active <span data-testid={`summary-grade-${g}-active`}>{on.filter((p) => isActive(liveOf(p), today)).length}</span></td>
              </tr>
            );
          })}
          {byStart.map((p, i) => (
            <tr key={p.name}>
              <td>Period {p.name}</td>
              <td />
              <td>Due <span data-testid={`summary-period-${p.name}-due-total`}><Fig>{periodDues[i]}</Fig></span></td>
              <td>Change <span data-testid={`summary-period-${p.name}-change`}>
                <Fig>{i === 0 ? '' : dueChange(periodDues[i - 1], periodDues[i])}</Fig></span></td>
            </tr>
          ))}
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td>Claims <span data-testid={`summary-status-${s}-count`}>{statusCount(all, s)}</span></td>
              <td />
            </tr>
          ))}
          <tr>
            <td>Review late</td>
            <td>Claims <span data-testid="summary-review-late-count">
              {all.filter((c) => isReviewLate(c, today, reviewSla)).length}</span></td>
            <td />
          </tr>
          {(voidReasons.data ?? []).map((r) => (
            <tr key={r.reason}>
              <td>Voided: {r.reason}</td>
              <td>Claims <span data-testid={`summary-void-${r.reason}-count`}>
                {all.filter((c) => c.status === 'VOID' && c.voidReason === r.reason).length}</span></td>
              <td />
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}
import { useEffect, useState } from 'react';
import { useIsFetching, useQuery } from '@tanstack/react-query';
import { listPeople, peopleKey } from '../people/api';
import { usePersonDues } from '../rates/DueTotal';
import { useOverdue } from '../rates/Overdue';
import { formatCents, hundredths, trimmedSum } from '../rates/api';
import { useAsOf } from '../sheet/AsOf';
import { descendantsKey, listDescendants, liveKey } from '../sheet/api';
import { Fig } from '../session/Fig';
import { GRADES } from '../people/api';
import { claimsKey, listClaims } from '../claims/api';
import { STATUSES, statusCount, useGradeDues } from './Summary';

/** A sheet's own figures: each person's names (their name and aliases), due-total and overdue-total as
 *  their row shows them, and per grade and status the figures as the sheet's summary shows them. */
type Figures = { names: string[][]; dues: Array<string | null>; overdues: string[]; grades: Record<string, string>;
  statuses: Record<string, number> };

const nameKey = (name: string) => name.trim().toLowerCase();

/** How many people over the tree: people whose names or aliases match (as names are compared) are one. */
function distinctPeople(names: string[][]): number {
  const parent = names.map((_, i) => i);
  const find = (i: number): number => (parent[i] === i ? i : (parent[i] = find(parent[i])));
  const seen = new Map<string, number>();
  names.forEach((ns, i) => ns.forEach((n) => {
    const k = nameKey(n);
    const j = seen.get(k);
    if (j === undefined) seen.set(k, i);
    else parent[find(i)] = find(j);
  }));
  return names.filter((_, i) => find(i) === i).length;
}

/** As the screen shows the sheet: as of its date while one is set, each sheet as it stood then. */
function useFigures(sheetId: string, user: string): Figures {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const statuses = Object.fromEntries(STATUSES.map((s) => [s, statusCount(claims.data, s)]));
  return { names: (people.data ?? []).map((p) => [p.name, ...p.aliases]), dues: usePersonDues(sheetId, user),
    overdues: useOverdue(sheetId, user).perPerson, grades: useGradeDues(sheetId, user), statuses };
}

/** Works out one descendant sheet's own figures and hands them up; shows nothing. */
function Descendant({ sheetId, user, report }: { sheetId: string; user: string; report: (id: string, f: Figures) => void }) {
  const f = useFigures(sheetId, user);
  useEffect(() => report(sheetId, f), [sheetId, JSON.stringify(f)]);
  return null;
}

/** The consolidated figures over the sheet and all its descendants (its children, theirs, ...): the
 *  number of people, each counted once (people whose names or aliases match, as names are compared, are
 *  one); the due- and overdue-total of every person of the tree as their row shows it, added up leaving
 *  out the single highest and lowest over the whole tree when three or more have one; per grade,
 *  each sheet's due-total of that grade (retired people left out, as its summary shows it) added up; per
 *  status, the number of claims in it over the tree.
 *  While the screen shows the sheet as of a date, every sheet of the tree is as it stood at the end of
 *  that day, with that date as its today; the tree itself is the one the sheets' parents make now. */
export function Consolidated({ sheetId, user }: { sheetId: string; user: string }) {
  const [asOf] = useAsOf();
  // The tree is the one the sheets' parents make now, even while the screen shows a date.
  const live = asOf !== '';
  const own = useFigures(sheetId, user);
  const descendants = useQuery({ queryKey: liveKey(descendantsKey(sheetId), live), queryFn: () => listDescendants(sheetId, live) });
  const ids = descendants.data ?? [];
  const [reported, setReported] = useState<Record<string, Figures>>({});
  const report = (id: string, f: Figures) => setReported((r) => ({ ...r, [id]: f }));
  // A descendant's figures count once its own queries have been read afresh.
  const fetching = useIsFetching({ predicate: (q) => q.queryKey[0] === 'sheet' && ids.includes(q.queryKey[1] as string) });
  const ready = descendants.isSuccess && fetching === 0 && ids.every((id) => reported[id] !== undefined);
  const all = [own, ...ids.map((id) => reported[id]).filter((f): f is Figures => f !== undefined)];
  const sum = (pick: (f: Figures) => string) => formatCents(all.reduce((t, f) => t + hundredths(pick(f)), 0n));
  return (
    <p>
      {ids.map((id) => <Descendant key={id} sheetId={id} user={user} report={report} />)}
      Consolidated: people <span data-testid="consolidated-people-count">{ready ? distinctPeople(all.flatMap((f) => f.names)) : ''}</span>
      {' · '}due <span data-testid="consolidated-due-total"><Fig>{ready ? trimmedSum(all.flatMap((f) => f.dues)) : ''}</Fig></span>
