#!/usr/bin/env bash
# Start the Spring Boot app on $PORT (main class net.officefloor.hq.app.Application). On boot, Flyway
# migrates the empty in-memory H2 up to the current schema; Spring serves the SPA (static/) and the
# app's REST endpoints. Returns once
# launching; poll /actuator/health for readiness.
set -euo pipefail
cd "$(dirname "$0")/.."
mkdir -p .run

: "${PORT:?PORT must be set}"
JAR="$(ls -t target/*.jar 2>/dev/null | head -n1 || true)"
[ -n "$JAR" ] || { echo "no jar in target/ — run bin/build first" >&2; exit 1; }

# Known audit file (the file-based test-assertion channel). Absolute so app + tests agree.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

nohup java -jar "$JAR" --server.port="$PORT" --spring.profiles.active=e2e > .run/app.log 2>&1 &
echo $! > .run/app.pid
import { SheetBody } from '../../slots/defs/sheetBody';
import { Classic } from './Classic';
import { CompareSheet } from './CompareSheet';
import { Consolidated } from './Consolidated';
import { Dashboard } from './Dashboard';
import { Header } from './Header';
import { Summary } from './Summary';
import { TreeSearch } from './TreeSearch';

export const contributions = [
  SheetBody.fill({ order: -100, Component: Header }),
  SheetBody.fill({ order: -99, Component: Consolidated }),
  SheetBody.fill({ order: -98, Component: TreeSearch }),
  SheetBody.fill({ order: -97, Component: Dashboard }),
  SheetBody.fill({ order: 27, Component: Summary }),
  SheetBody.fill({ order: 27.5, Component: CompareSheet }),
  SheetBody.fill({ order: 28, Component: Classic }),
];

